def find_middle(s):
    if not isinstance(s, str):
        return -1
    digits = []
    for c in s:
        if c.isdigit():
            digits.append(int(c))
    if not digits:
        return -1
    product = 1
    for d in digits:
        product *= d
    product_str = str(product)
    length = len(product_str)
    if length % 2 == 1:
        return int(product_str[length // 2])
    else:
        middle = product_str[length // 2 - 1 : length // 2 + 1]
        if middle[0] == '0':
            return int(middle[1])
        return int(middle)
